begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('41000000-0000-0000-0000-000000000001'),('41000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"41000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.user_settings(user_id) values ('41000000-0000-0000-0000-000000000001')$$,'owner creates settings without losing theme defaults');
select lives_ok($$update public.user_settings set appearance='{"accent":"#aaccee","font":"serif","size":18,"width":"wide"}'$$,'owner saves bounded style tokens');
select throws_ok($$update public.user_settings set appearance='{"accent":"url(https://tracker.invalid)"}'$$,'23514',null,'CSS injection rejected');
select throws_ok($$update public.user_settings set appearance='{"body":"private journal"}'$$,'23514',null,'nonappearance fields rejected');
select throws_ok($$update public.user_settings set appearance='{"size":999}'$$,'23514',null,'unsupported font size rejected');
select throws_ok($$update public.user_settings set appearance='{"font":null}'$$,'23514',null,'null style fields rejected');
select lives_ok($$insert into public.public_profiles(username,display_name,cover_id) values ('synthetic_style_a','Synthetic A','forest-light')$$,'owner selects a public banner while profile remains hidden');
select is(public.my_public_profile()->>'cover_id','forest-light','own-profile RPC returns approved banner only');
select ok(not(public.my_public_profile()?'user_id'),'own-profile response still hides owner key');
select throws_ok($$update public.public_profiles set cover_id='https://private.invalid/a.jpg'$$,'23514',null,'arbitrary profile image paths rejected');
select set_config('request.jwt.claims','{"sub":"41000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.user_settings),0::bigint,'B cannot read A appearance');
select lives_ok($$update public.user_settings set appearance='{}' where user_id='41000000-0000-0000-0000-000000000001'$$,'B update affects no owner rows');
select is((select count(*) from public.public_profiles where username='synthetic_style_a'),0::bigint,'B cannot read hidden profile banner');
select set_config('request.jwt.claims','{"sub":"41000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((select appearance->>'font' from public.user_settings),'serif','B did not overwrite A style');
select lives_ok($$update public.public_profiles set visible=true where username='synthetic_style_a'$$,'profile banner becomes public only on opt-in');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok($$select appearance from public.user_settings$$,'42501',null,'anonymous appearance access denied');
select is((select cover_id from public.public_profiles where username='synthetic_style_a'),'forest-light','anonymous reads deliberate public banner');
select throws_ok($$select user_id from public.public_profiles$$,'42501',null,'public banner does not expose ownership');
select * from finish();
rollback;
